p='item_context.av'; s=open(p).read()
def rep(o,n):
    global s; assert s.count(o)==1,o; s=s.replace(o,n)
rep('''    /// The item's id, where its file's items are read (`file_abouts`).
    id: int = 0,
}''','''    /// The item's id, where its file's items are read (`file_abouts`).
    id: int = 0,
    /// Which of the forms a law reads at its own nodes the item holds (`WHEN_SHAPE`,
    /// `TYPED_PATTERN_SHAPE`), so a law over a form the item lacks reads nothing more of it.
    shapes: List<string> = [],
}

/// The shape of an item holding a `when`.
export const WHEN_SHAPE: string = "when"

/// The shape of an item holding a type pattern (`c: T`).
export const TYPED_PATTERN_SHAPE: string = "typed"

/// The shapes among `WHEN_SHAPE` and `TYPED_PATTERN_SHAPE` the nodes of `store` hold.
fn shapes_held(store: SyntaxArena) -> List<string> {
    let whens = every_expr(store).any((e) -> store.expr(e) is .When)
    let typed = (0..store.pat_count()).any((i) -> store.pat(PatId { index: i }) is .Typed)
    (if whens { [WHEN_SHAPE] } else { [] }).concat(if typed { [TYPED_PATTERN_SHAPE] } else { [] })
}''')
rep('''        instance_words: distinct([w! for e in every_expr(store) for w in [store.instance_word(e)] if w != null]),''','''        instance_words: distinct([w! for e in every_expr(store) for w in [store.instance_word(e)] if w != null]),
        shapes: shapes_held(store),''')
rep('type ItemSaid = { runs: bool, worn: List<NameWorn>, declares: bool = false, instanced: bool = false }','type ItemSaid = { runs: bool, worn: List<NameWorn>, declares: bool = false, instanced: bool = false, shapes: List<string> = [] }')
rep('''                    instanced: !about.instance_words.is_empty(),
                }''','''                    instanced: !about.instance_words.is_empty(),
                    shapes: about.shapes,
                }''')
open(p,'w').write(s)
EOF
grep -n "PatId" item_context.av | head -3; grep -n "^use core" -A12 item_context.av | grep -n "PatId\|SyntaxArena"

