/// The part of `before_parts` saying whether an item before the item `at` runs.
fn runs_part(at: int) -> string { "r${at}" }

/// The part of `before_parts` holding what the items before the item `at` write.
fn front_part(at: int) -> string { "f${at}" }

/// What the items `ids` of `file` write that the items after them read, gathered in order.
fn fronts_gathered(engine: QueryEngine, file: SourceFileAddress, ids: List<int>) -> ItemFront { fronts_joined([item_front(engine, file, i) for i in ids]) }

/// `fronts`, one after another.
fn fronts_joined(fronts: List<ItemFront>) -> ItemFront { ItemFront { binds: flatten([f.binds for f in fronts]), uses: flatten([f.uses for f in fronts]) } }

/// The names a written item declares, each with its face, as its meaning's tape says them.
@derive(Saved)
type ItemDeclares = { names: List<TapeName> }

/// THE INTERFACE of the written item `at` of `file`, as its meaning's tape says it, in two parts:
/// what it says of itself (`said`), and each name it declares with its face (`declares`). One
/// answer per item, cut part by part where each comes out the same, so a new body for one of its
/// fns moves no reader of it, and a signature moves no reader of what the item says of itself.
@cut_parted_query
fn item_summary(engine: QueryEngine, file: SourceFileAddress, at: int) -> AnswerParts {
    let tape = meant_tape(engine, file, item_under(engine, file, at))
    let about = about_of(tape_about(tape))
    let declares = tape_declares(tape)
    answer_parts(
        [
            NamedValue {
                name: SAID_PART,
                value: ItemSaid {
                    runs: about.runs,
                    worn: about.worn,
                    declares: !declares.is_empty(),
                    instanced: !about.instance_words.is_empty(),
                }
                    .saved_bytes(),
            },
            NamedValue {
                name: DECLARES_PART,
                value: ItemDeclares { names: declares }.saved_bytes(),
            },
        ],
    )
}

/// The part of `item_summary` holding what its item says of itself.
const SAID_PART: string = "said"

/// The part of `item_summary` holding the names its item declares.
const DECLARES_PART: string = "declares"

