/// The arm the body's typing refused as `r`, against the anchor it names; none for any other refusal.
fn arm_refused(r: RefusedSeat, text: string) -> List<Found> {
    match r.seat {
        .Arm(seated) -> [
            said_apart(
                span_of(r.at),
                r.found,
                if seated { SEAT } else { FIRST_ARM },
                r.want,
                conversion_spelled(r.found, r.want, text_at(r.at, text)),
            ),
        ],
        rest -> [],
    }
}

const SEAT: string = "the seat"

const FIRST_ARM: string = "the first arm"

/// The text standing at `at`; absent where the file doesn't hold it.
fn text_at(at: FindingAt?, text: string) -> string? {
    let held? = at else { return null }
    if held.hi > text.length { null } else { text.substring(held.lo, held.hi) }
}

/// The conversion the old path offers of a value spelled `found`, written `shown`, into a seat
/// spelled `want`: the value as a list's one element, or a scalar interpolated into text.
fn conversion_spelled(found: string, want: string, shown: string?) -> Conversion? {
    let s? = shown else { return null }
    if want == "List<${found}>" { return wrapped(s) }
    if want == "string" && ["int", "float", "bool"].contains(found) { interpolation(s) } else { null }
}

/// The one conversion a seat's value of type `found`, written `shown`, offers into a seat spelled
/// `want`: the arms' own, or a nullable handed to the seat that wants what it carries, asserted
/// present.
fn seat_conversion(found: string, want: string, shown: string?) -> Conversion? {
    let s? = shown else { return null }
    let arms = conversion_spelled(found, want, s)
    if arms != null || found != "${want}?" { return arms }
    presence_asserted(s, if postfix_written(s) { s } else { "(${s})" })
}

/// Whether `s` reads as one operand a postfix binds to: a name, a path of names, or a call.
fn postfix_written(s: string) -> bool {
    !s.contains(" ") && !s.starts_with("(") && !s.contains("?") && !s.contains("!")
}

/// The body of the fn `s` declares where it answers `void`; none for any other statement.
fn void_fn_bodies(engine: QueryEngine, file: SourceFileAddress, item: ReadItem, s: StmtId) -> List<
    ExprId?,
> {
    let parts? = item.store.fn_parts(s) else { return [] }
    let sig? = fn_signature(engine, file, parts.name) else { return [] }
    if sig.answer.spelled() == "void" { [parts.body] } else { [] }
}

/// The bodies of the methods and statics each impl the written item `at` of `file` writes answers
/// `void` from.
fn void_method_bodies(engine: QueryEngine, file: SourceFileAddress, at: int, item: ReadItem) -> List<
    ExprId,
> {
    [p!.body for a in impls_at(engine, file, at) for s in impl_fns(item, a) for p in [item.store.fn_parts(s)] if p != null && answers_void(method_signature(engine, a, p!.name))]
}

/// Whether `sig` answers `void`; absent, it answers nothing known.
fn answers_void(sig: FnSignature?) -> bool {
    let known? = sig else { return false }
    known.answer.spelled() == "void"

/// Where an arm's refusal points: its value.
fn arm_span(t: TypedNodes, v: ExprId) -> Span? { t.store.expr_span(v) }

/// a `match`'s arms meet at one type
export law match_arms_agree {
    kind: "type.match"
    reads_view: arms_disagreeing
    voice: disagreeing_words
    witness: "enum H {\n    A\n    B\n}\n\nfn note(n: int) { }\n\nfn f(h: H) -> int {\n    match h {\n        .A -> note(1),\n        rest -> {}\n    }\n    2\n}\n\nf(H.A)\n"
}

fn disagreeing_words(a: List<string>) -> Voice {
    Voice {
        message: arms_disagreement("a `match`'s arms", a[0], a[1], a[2]),
        label: this_is(a[0]),
        help: if a[3].is_empty() { value_wanted(a[2]) } else { a[3] },
    }
}
