fn default_law(
    mut cx: TypeCx,
    e: ExprId,
    conds: List<ExprId>,
    values: List<ExprId>,
    defaults: List<ExprId>,
) -> bool {
    if defaults.is_empty() {
        cx.emit(no_total_arm(cx, e))
        return true
    }
