//! WHERE A `match`'S ARMS MEET AT NO TYPE: an arm answering what the others' answer can't join,
//! judged as the old path's arms law judges them — against the seat where one plants its want on
//! the arms, else against the first arm joined with each arm in turn, as the body's typing refused
//! it; one a `void` fn, method or static ends on against the seat, read off the item's typed
//! nodes. A build that let them through would join values of two types, or a value with nothing.
use core.{ExprId, OwnType, SignedType, Span, StmtId, flatten, owned_type}
use compiler.laws.{Found, FoundFix, law}
use diagnostics.{Voice}
use features.{
    Conversion,
    arms_disagreement,
    interpolation,
    presence_asserted,
    this_is,
    value_wanted,
    wrapped,
}
use @std.program.address.{SourceFileAddress}
use @std.program.query_engine.{QueryEngine}
use @std.program.source_facts.{source_text}

/// What a `match`'s arms are judged against: its first arm's answer, or the seat's.
type ArmsAnchor = { name: string, want: SignedType }

/// Every arm of a `match` in the written item `view` shows that its anchor can't join: each the
/// body's typing refused as an arm, and each of a `match` a `void` fn ends on.
fn arms_disagreeing(view: ItemView) -> List<Found> {
    let item = view.item
    if !item.store.refusals().is_empty() { return [] }
    let void_tails = [b! for s in item.stmts for b in void_fn_bodies(view.engine, view.file, item, s) if b != null]
        .concat(void_method_bodies(view.engine, view.file, view.at, item))
    let text = item_under(view.engine, view.file, view.at).text
    flatten([arm_refused(r, text) for r in refused_in(view.engine, view.file, view.at)])
        .concat(
            flatten(
                [void_disagreeing(t, void_tails, text) for t in item_typed_nodes(view.engine, view.file, view.at, item)],
            ),
        )
}

