python3 - <<'EOF'
p='/work/avra/packages/std-avrac/src/compiler/tests/aftercall_test.av'; s=open(p).read()
o='''    then "the call that runs a `defer` carries no test; the deferred closure's own call is its own" {
        // nap's row call, the closure's call to nap, and the entry's call to work
        tests(
            napping().concat(["fn work() -> int {", "    defer { nap() }", "    7", "}", "work()"]),
        ) == 3
    }'''
assert o in s
n='''    then "the call that runs a `defer` carries no test; the deferred closure's own call is its own" {
        // relay's call through a value, the closure's call to relay, and the entry's call to work: a
        // call through a value may reach a cancel point, so each is tested, yet it parks nothing, so
        // the cleanup is no unbounded wait (a deferred call that parks is refused before it lowers)
        tests(
            [
                "fn quiet() { }",
                "fn relay(f: fn()) { f() }",
                "fn work(f: fn()) -> int {",
                "    defer { relay(f) }",
                "    7",
                "}",
                "work(quiet)",
            ],
        ) == 3
    }'''
s=s.replace(o,n); open(p,'w').write(s)
EOF
