export fn unenumerated_match(found: string) -> Voice {
    Voice {
        message: "`match` chooses over an enum, found `${found}`",
        label: this_is(found),
        help: "match literals (`5 -> …`), bind the value (`n -> …`), or declare an `enum` for variant patterns (`.a`)",
    }
}

