/// should call, but it never traps the compiler on a shape it was
/// never built for) — `problems` is what actually stops the build,
/// spoken as real diagnostics at the declaration itself.
/// `@unique(a, b, …)` on a `@model` type: no two rows hold the same values in those fields together —
/// a key over several columns, declared on the model itself. Its fields are the type's own, named
/// bare and checked where they're written; each must be a column the model stores, and named once.
/// A key declared twice is `@model`'s to refuse, once.
export fn unique(t: Type, ..fields: List<Field>) -> List<Diagnostic> {
    let key = [f.name for f in fields]
    let at = key_written(t, key)?.at
    if key.is_empty() { return [model_key_empty(t, at)] }
    [model_key_unstored(t, n, at) for n in key if !stored(t).any(it.name == n)]
        .concat([model_key_repeats(t, n, at) for j, n in key if key.index_of(n) < j])
}

/// The `@unique` the type `t` wears over the fields `key`, in their order.
fn key_written(t: Type, key: List<string>) -> Annotation? { t.annotations.find(it.name == "unique" && it.args.join(",") == key.join(",")) }

/// The keys a `@model` type declares on itself, `@unique(a, b, …)`, each as the fields it names.
fn model_keys(t: Type) -> List<List<string>> { [a.args for a in t.annotations if a.name == "unique" && !a.args.is_empty()] }

export fn model(t: Type) -> Declared {
    Declared { made: Model.derive(t), problems: shape_problems(t) }
}

/// `@model`'s contract: every refusal here is a package-namespaced
/// `Diagnostic` (`@std/db: no_id_field`, ...), in the law's own words.
fn shape_problems(t: Type) -> List<Diagnostic> {
    if t.variants.length > 0 { return [enum_not_supported(t)] }
    if !has_id_field(t) { return [no_id_field(t)] }
    [soft_delete_kind(f) for f in t.fields if is_mark(f, "soft_delete") && !nullable_int(f.kind)]
        .concat([auto_kind(f) for f in t.fields if is_mark(f, "auto") && !plain_int(f.kind)])
        .concat([not_stored(f) for f in t.fields if unheld(f)])
        .concat([p for f in t.fields for p in key_problems(t, f)])
        .concat(model_keys_twice(t))
}

/// Each key `t` declares on itself again, refused at the second `@unique` writing it.
fn model_keys_twice(t: Type) -> List<Diagnostic> {
    let written = [a for a in t.annotations if a.name == "unique" && !a.args.is_empty()]
    [model_key_twice(t, a.args, a.at) for j, a in written if written.take(j).any(it.args.join(",") == a.args.join(","))]
}

/// What is wrong with the several-column keys a field's marks declare: a
/// name the model stores no column for, a field named twice in one key,
/// one key declared twice.
        "declare it `${f.name}: int? = null`",
    )
}

fn unique_unstored(t: Type, f: Field, n: string) -> Diagnostic {
    refuse_as_at(
        "unique_unstored",
        f.at,
        "`@unique(…)` names the fields a value is unique within, each one a column, and `${t.name}` stores none for `${n}`",
        "name fields `${t.name}` stores: ${[g.name for g in stored(t) if g.name != f.name].join(", ")}",
    )
}

fn model_key_unstored(t: Type, n: string, at: Loc?) -> Diagnostic {
    refuse_as_at(
        "unique_unstored",
        at,
        "`@unique(…)` names the fields a value is unique within, each one a column, and `${t.name}` stores none for `${n}`",
        "name fields `${t.name}` stores: ${[g.name for g in stored(t)].join(", ")}",
    )
}

fn model_key_repeats(t: Type, n: string, at: Loc?) -> Diagnostic {
    refuse_as_at(
        "unique_repeats",
        at,
        "a key holds each field once, and this one on `${t.name}` holds `${n}` twice",
        "name `${n}` once",
    )
}

fn model_key_twice(t: Type, k: List<string>, at: Loc?) -> Diagnostic {
    refuse_as_at(
        "unique_twice",
        at,
        "a key is declared once, and the key over ${["`${n}`" for n in k].join(", ")} stands on `${t.name}` twice",
        "write the annotation once",
    )
}

fn model_key_empty(t: Type, at: Loc?) -> Diagnostic {
    refuse_as_at(
        "unique_empty",
        at,
        "a key names the fields a row is unique by, and this one on `${t.name}` names none",
        "name its fields — `@unique(a, b)`",
    )
}

fn unique_repeats(f: Field, n: string) -> Diagnostic {
    refuse_as_at(
        "unique_repeats",
        f.at,
        "a key holds each field once, and this one on `${f.name}` holds `${n}` twice",
        "name `${n}` once, and never the field the mark stands on",
    )
}

fn unique_twice(f: Field, k: List<string>) -> Diagnostic {
    refuse_as_at(
        "unique_twice",
        f.at,
        "a key is declared once, and the key over ${["`${n}`" for n in k].join(", ")} stands on `${f.name}` twice",
        "write the mark once",
    )
}

fn auto_kind(f: Field) -> Diagnostic {
    refuse_as_at(
        "auto_kind",
        f.at,
        "`@auto` is a time the database sets, an integer, and `${f.name}` is `${f.ty}`",
        "declare it `${f.name}: int`",
    )
}

